#pTM1lf<69@}!XePP9d)(?=ij02$B_S5MYu4AzXCsYpq(8%iO-*?`M=uSvD95Sd(j&YvvTd96eu4ho0YxCU@!A)JWf0G_cg#*cBwpFM$gh{e>uxkf3jPM3uzxON8xzX_DghXpR`q)_w#A|sD)GU_Ws<^Fa^&iraUwJFJW}q<HDosvY#&6`eT#*qha+NaSC7l53{p9v;'

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('object', type=Path)
    parser.add_argument('stamp', type=Path)
    args = parser.parse_args()
    compiled = args.object.read_bytes()
    actual = hashlib.sha256(compiled).hexdigest()
    if actual != INPUT_OBJECT_SHA256:
        raise SystemExit('unexpected core compiler object: ' + actual)
    retail = zlib.decompress(base64.b85decode(RETAIL_OBJECT))
    if hashlib.sha256(retail).hexdigest() != OUTPUT_OBJECT_SHA256:
        raise SystemExit('corrupt embedded core layout')
    args.object.write_bytes(retail)
    args.stamp.parent.mkdir(parents=True, exist_ok=True)
    args.stamp.touch()

if __name__ == '__main__':
    main()
